# Let's manually examine the input/output pairs to understand the transformations
inputs = ['vjch', 'cjvu', 'gw', 'gdek', 'fkekvf']
outputs = ['vjgh', 'gjvu', 'vww', 'vwdek', 'fkekvf']

print("Input strings:", inputs)
print("Output strings:", outputs)
print()

# Let's compare each pair manually to see what changes
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Pair {i}: '{inp}' -> '{out}'")
    # Find differences
    diff_positions = []
    for j, (c_in, c_out) in enumerate(zip(inp, out)):
        if c_in != c_out:
            diff_positions.append((j, c_in, c_out))

    # Check if one string is longer
    if len(inp) != len(out):
        if len(inp) > len(out):
            # String got shorter
            for j in range(len(out)):
                if j >= len(inp) or inp[j] != out[j]:
                    diff_positions.append((j, inp[j], 'DELETED'))
            # Check if extra chars at end
            if len(inp) > len(out):
                for j in range(len(out), len(inp)):
                    diff_positions.append((j, inp[j], 'DELETED'))
        else:
            # String got longer
            for j in range(len(inp)):
                if inp[j] != out[j]:
                    diff_positions.append((j, 'ADDED', out[j]))
            # Check if extra chars at end
            if len(out) > len(inp):
                for j in range(len(inp), len(out)):
                    diff_positions.append((j, 'ADDED', out[j]))

    print(f"  Differences: {diff_positions}")
    print()

